#include <iostream>
#include <cstdlib>

int main() {
    // 🎛️ TWEAK THESE
    const int SECRET_MIN = 1;
    const int SECRET_MAX = 20;
    const unsigned SEED = 7;

    std::srand(SEED);
    int secret = SECRET_MIN + std::rand() % (SECRET_MAX - SECRET_MIN + 1);
    int low = SECRET_MIN, high = SECRET_MAX;
    int attempts = 0;

    std::cout << "Guess Duel: find " << SECRET_MIN << "-" << SECRET_MAX << "\n";
    while (true) {
        int guess = (low + high) / 2; // binary-search style player
        ++attempts;
        std::cout << "Attempt " << attempts << ": " << guess;
        if (guess == secret) {
            std::cout << " -> correct!\n";
            break;
        } else if (guess < secret) {
            std::cout << " -> too low\n";
            low = guess + 1;
        } else {
            std::cout << " -> too high\n";
            high = guess - 1;
        }
    }
    std::cout << "Won in " << attempts << " tries. Secret was " << secret << ".\n";
    return 0;
}

