std::string caesar(const std::string& text, int shift) {
    std::string out = text;
    for (char& ch : out) {
        if (ch >= 'a' && ch <= 'z')
            ch = char('a' + (ch - 'a' + shift + 26) % 26);
        else if (ch >= 'A' && ch <= 'Z')
            ch = char('A' + (ch - 'A' + shift + 26) % 26);
    }
    return out;
}

int main() {
    // 🎛️ TWEAK THESE
    std::string message = "CodeItAll Cadets Learn C++";
    int shift = 4;

    std::string secret = caesar(message, shift);
    std::cout << "Plain : " << message << "\n";
    std::cout << "Secret: " << secret << "\n";
    std::cout << "Back  : " << caesar(secret, -shift) << "\n";
    return 0;
}

