bool is_prime(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    int lim = static_cast<int>(std::sqrt(n));
    for (int d = 3; d <= lim; d += 2)
        if (n % d == 0) return false;
    return true;
}

int main() {
    // 🎛️ TWEAK THESE
    const int FROM = 2;
    const int TO = 100;
    const int COLS = 8;

    int col = 0, found = 0;
    std::cout << "Primes from " << FROM << " to " << TO << ":\n";
    for (int n = FROM; n <= TO; ++n) {
        if (!is_prime(n)) continue;
        std::cout << n << '\t';
        ++found;
        if (++col == COLS) { std::cout << '\n'; col = 0; }
    }
    if (col) std::cout << '\n';
    std::cout << "Found " << found << " primes.\n";
    return 0;
}

