int score_password(const std::string& p) {
    int score = 0;
    bool lower = false, upper = false, digit = false, sym = false;
    if (p.size() >= 8) score += 2;
    if (p.size() >= 12) score += 2;
    for (char ch : p) {
        if (std::islower(static_cast<unsigned char>(ch))) lower = true;
        else if (std::isupper(static_cast<unsigned char>(ch))) upper = true;
        else if (std::isdigit(static_cast<unsigned char>(ch))) digit = true;
        else sym = true;
    }
    score += lower + upper + digit + sym;
    return score;
}

