enum class Light { Red, Green, Yellow };

const char* label(Light l) {
    switch (l) {
        case Light::Red: return "RED - stop";
        case Light::Green: return "GREEN - go";
        case Light::Yellow: return "YELLOW - slow";
    }
    return "?";
}

Light next(Light l) {
    switch (l) {
        case Light::Red: return Light::Green;
        case Light::Green: return Light::Yellow;
        case Light::Yellow: return Light::Red;
    }
    return Light::Red;
}

