#include <iostream>
#include <vector>
#include <utility>

using Grid = std::vector<std::vector<int>>;

int neighbors(const Grid& g, int r, int c) {
    int n = 0, R = (int)g.size(), C = (int)g[0].size();
    for (int dr = -1; dr <= 1; ++dr)
        for (int dc = -1; dc <= 1; ++dc) {
            if (!dr && !dc) continue;
            int rr = r + dr, cc = c + dc;
            if (rr >= 0 && rr < R && cc >= 0 && cc < C) n += g[rr][cc];
        }
    return n;
}

Grid step(const Grid& g) {
    Grid n = g;
    for (int r = 0; r < (int)g.size(); ++r)
        for (int c = 0; c < (int)g[0].size(); ++c) {
            int k = neighbors(g, r, c);
            n[r][c] = (g[r][c] ? (k == 2 || k == 3) : (k == 3));
        }
    return n;
}

void print(const Grid& g) {
    for (auto& row : g) {
        for (int v : row) std::cout << (v ? 'O' : '.');
        std::cout << "\n";
    }
    std::cout << "\n";
}

int main() {
    // 🎛️ TWEAK THESE
    const int GENS = 6;
    Grid g(12, std::vector<int>(20, 0));
    // glider
    g[1][2] = g[2][3] = g[3][1] = g[3][2] = g[3][3] = 1;

    for (int i = 0; i <= GENS; ++i) {
        std::cout << "gen " << i << "\n";
        print(g);
        g = step(g);
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>

using Maze = std::vector<std::string>;

bool dfs(Maze& m, int r, int c) {
    if (r < 0 || c < 0 || r >= (int)m.size() || c >= (int)m[0].size()) return false;
    if (m[r][c] == '#' || m[r][c] == '*') return false;
    bool end = m[r][c] == 'E';
    if (m[r][c] != 'S') m[r][c] = '*';
    if (end) return true;
    if (dfs(m, r + 1, c) || dfs(m, r - 1, c) || dfs(m, r, c + 1) || dfs(m, r, c - 1))
        return true;
    if (m[r][c] == '*') m[r][c] = '.';
    return false;
}

int main() {
    Maze m = {
        "S.#.E",
        ".#.#.",
        "...#.",
        ".###.",
        "....."
    };
    dfs(m, 0, 0);
    for (auto& row : m) std::cout << row << "\n";
    return 0;
}

