        {"Home", {"Cafe", "Park"}},
        {"Cafe", {"Home", "Lab"}},
        {"Park", {"Home", "Market"}},
        {"Lab", {"Cafe", "Studio"}},
        {"Market", {"Park", "Studio"}},
        {"Studio", {"Lab", "Market"}}
    };
    std::string start = "Home", goal = "Studio";

    std::queue<std::string> q;
    std::map<std::string, int> dist;
    q.push(start); dist[start] = 0;
    while (!q.empty()) {
        auto u = q.front(); q.pop();
        if (u == goal) break;
        for (auto& v : g[u]) if (!dist.count(v)) {
            dist[v] = dist[u] + 1;
            q.push(v);
        }
    }
    if (!dist.count(goal)) std::cout << "No path\n";
    else std::cout << start << " -> " << goal << " in " << dist[goal] << " hops\n";
    return 0;
}

