constexpr int magic_sum(const std::array<int, 9>& a) {
    // first row sum as representative when square is valid
    return a[0] + a[1] + a[2];
}

constexpr bool is_magic(const std::array<int, 9>& a) {
    const int t = 15;
    auto row = [&](int r) { return a[3*r] + a[3*r+1] + a[3*r+2]; };
    auto col = [&](int c) { return a[c] + a[3+c] + a[6+c]; };
    if (row(0) != t || row(1) != t || row(2) != t) return false;
    if (col(0) != t || col(1) != t || col(2) != t) return false;
    if (a[0] + a[4] + a[8] != t) return false;
    if (a[2] + a[4] + a[6] != t) return false;
    return true;
}

int main() {
